const users=$input.first().json||[];
const now=Date.now();
const noMfa=users.filter(u=>{
  const factors=u._embedded?.factors||[];
  return !factors.some(f=>f.status==='ACTIVE');
});
const classified=noMfa.map(u=>{
  const hours=Math.floor((now-new Date(u.created))/3600000);
  const isPriv=(u.profile?.userType||'').toLowerCase().includes('admin');
  let action='FIRST_REMINDER';
  if(isPriv&&hours>48) action='SUSPEND';
  else if(hours>48) action='ESCALATE';
  else if(hours>24) action='FINAL_REMINDER';
  return{...u.profile,user_id:u.id,hours_since_created:hours,is_privileged:isPriv,action};
});
const byAction={};
classified.forEach(u=>{if(!byAction[u.action])byAction[u.action]=[];byAction[u.action].push(u);});
return[{json:{total:users.length,no_mfa:noMfa.length,by_action:byAction,
  suspend_count:(byAction.SUSPEND||[]).length,escalate_count:(byAction.ESCALATE||[]).length}}];

